create or replace semantic view RETAIL_ANALYTICS_SV
	tables (
		CSA.TJ.ORDER_FACT primary key (ORDER_ID,ORDER_LINE) comment='Central fact table for retail orders at order-line grain',
		CSA.TJ.CUSTOMER_DIM primary key (CUSTOMER_KEY) comment='Customer dimension with demographics and lifetime metrics',
		CSA.TJ.PRODUCT_DIM primary key (PRODUCT_KEY) comment='Product dimension with catalog attributes',
		CSA.TJ.STORE_DIM primary key (STORE_KEY) comment='Store dimension for order placement and fulfillment locations',
		CSA.TJ.DATE_DIM primary key (DATE_KEY) comment='Date dimension for order, ship, and return dates',
		CSA.TJ.PROMO_DIM primary key (PROMO_KEY) comment='Promotion dimension with discount and campaign details'
	)
	relationships (
		ORDER_TO_CUSTOMER as ORDER_FACT(CUSTOMER_KEY) references CUSTOMER_DIM(CUSTOMER_KEY),
		ORDER_TO_ORDER_DATE as ORDER_FACT(ORDER_DATE_KEY) references DATE_DIM(DATE_KEY),
		ORDER_TO_SHIP_DATE as ORDER_FACT(SHIP_DATE_KEY) references DATE_DIM(DATE_KEY),
		ORDER_TO_RETURN_DATE as ORDER_FACT(RETURN_DATE_KEY) references DATE_DIM(DATE_KEY),
		ORDER_TO_PRODUCT as ORDER_FACT(PRODUCT_KEY) references PRODUCT_DIM(PRODUCT_KEY),
		ORDER_TO_PROMO as ORDER_FACT(PROMO_KEY) references PROMO_DIM(PROMO_KEY),
		ORDER_TO_ORDER_STORE as ORDER_FACT(ORDER_STORE_KEY) references STORE_DIM(STORE_KEY),
		ORDER_TO_SHIP_STORE as ORDER_FACT(SHIP_STORE_KEY) references STORE_DIM(STORE_KEY)
	)
	facts (
		ORDER_FACT.QUANTITY_ORDERED as QUANTITY_ORDERED,
		ORDER_FACT.QUANTITY_RETURNED as QUANTITY_RETURNED,
		ORDER_FACT.UNIT_PRICE as UNIT_PRICE,
		ORDER_FACT.UNIT_COST as UNIT_COST,
		ORDER_FACT.DISCOUNT_AMOUNT as DISCOUNT_AMOUNT,
		ORDER_FACT.SHIPPING_AMOUNT as SHIPPING_AMOUNT,
		ORDER_FACT.TAX_AMOUNT as TAX_AMOUNT,
		ORDER_FACT.GROSS_REVENUE as GROSS_REVENUE,
		ORDER_FACT.NET_REVENUE as NET_REVENUE,
		ORDER_FACT.GROSS_PROFIT as GROSS_PROFIT,
		ORDER_FACT.NET_PROFIT as NET_PROFIT,
		ORDER_FACT.DAYS_TO_SHIP as DAYS_TO_SHIP,
		ORDER_FACT.IS_FIRST_ORDER as IS_FIRST_ORDER,
		ORDER_FACT.IS_RETURNED as IS_RETURNED,
		ORDER_FACT.IS_CANCELLED as IS_CANCELLED,
		CUSTOMER_DIM.LIFETIME_ORDER_COUNT as LIFETIME_ORDER_COUNT,
		CUSTOMER_DIM.LIFETIME_REVENUE as LIFETIME_REVENUE,
		CUSTOMER_DIM.IS_ACTIVE as IS_ACTIVE,
		CUSTOMER_DIM.IS_EMAIL_OPT_IN as IS_EMAIL_OPT_IN,
		PRODUCT_DIM.PROD_UNIT_COST as product_dim.UNIT_COST,
		PRODUCT_DIM.PROD_UNIT_PRICE as product_dim.UNIT_PRICE,
		PRODUCT_DIM.WEIGHT_LBS as WEIGHT_LBS,
		PRODUCT_DIM.PROD_IS_ACTIVE as product_dim.IS_ACTIVE,
		PRODUCT_DIM.IS_PRIVATE_LABEL as IS_PRIVATE_LABEL,
		PRODUCT_DIM.IS_SEASONAL as IS_SEASONAL,
		STORE_DIM.SQUARE_FOOTAGE as SQUARE_FOOTAGE,
		STORE_DIM.ANNUAL_LEASE_COST as ANNUAL_LEASE_COST,
		STORE_DIM.STORE_IS_ACTIVE as store_dim.IS_ACTIVE,
		STORE_DIM.HAS_CAFE as HAS_CAFE,
		STORE_DIM.HAS_CURBSIDE as HAS_CURBSIDE,
		DATE_DIM.DAY_OF_MONTH as DAY_OF_MONTH,
		DATE_DIM.WEEK_OF_YEAR as WEEK_OF_YEAR,
		DATE_DIM.MONTH_NUMBER as MONTH_NUMBER,
		DATE_DIM.QUARTER as QUARTER,
		DATE_DIM.YEAR as YEAR,
		DATE_DIM.IS_WEEKEND as IS_WEEKEND,
		DATE_DIM.IS_HOLIDAY as IS_HOLIDAY,
		PROMO_DIM.DISCOUNT_PCT as DISCOUNT_PCT,
		PROMO_DIM.PROMO_COST as PROMO_COST,
		PROMO_DIM.MIN_ORDER_AMOUNT as MIN_ORDER_AMOUNT,
		PROMO_DIM.IS_STACKABLE as IS_STACKABLE
	)
	dimensions (
		ORDER_FACT.ORDER_ID as ORDER_ID,
		ORDER_FACT.ORDER_LINE as ORDER_LINE,
		ORDER_FACT.ORDER_CHANNEL as ORDER_CHANNEL,
		ORDER_FACT.SHIP_METHOD as SHIP_METHOD,
		ORDER_FACT.ORDER_STATUS as ORDER_STATUS,
		CUSTOMER_DIM.CUSTOMER_KEY as customer_dim.CUSTOMER_KEY,
		CUSTOMER_DIM.CUSTOMER_ID as CUSTOMER_ID,
		CUSTOMER_DIM.FIRST_NAME as FIRST_NAME,
		CUSTOMER_DIM.LAST_NAME as LAST_NAME,
		CUSTOMER_DIM.EMAIL as EMAIL,
		CUSTOMER_DIM.PHONE as PHONE,
		CUSTOMER_DIM.CUST_CITY as customer_dim.CITY,
		CUSTOMER_DIM.CUST_STATE as customer_dim.STATE,
		CUSTOMER_DIM.ZIP_CODE as ZIP_CODE,
		CUSTOMER_DIM.CUST_REGION as customer_dim.REGION,
		CUSTOMER_DIM.CUSTOMER_SEGMENT as CUSTOMER_SEGMENT,
		CUSTOMER_DIM.LOYALTY_TIER as LOYALTY_TIER,
		CUSTOMER_DIM.ACQUISITION_CHANNEL as ACQUISITION_CHANNEL,
		CUSTOMER_DIM.FIRST_ORDER_DATE as FIRST_ORDER_DATE,
		PRODUCT_DIM.PRODUCT_KEY as product_dim.PRODUCT_KEY,
		PRODUCT_DIM.PRODUCT_ID as PRODUCT_ID,
		PRODUCT_DIM.PRODUCT_NAME as PRODUCT_NAME,
		PRODUCT_DIM.CATEGORY as CATEGORY,
		PRODUCT_DIM.SUBCATEGORY as SUBCATEGORY,
		PRODUCT_DIM.BRAND as BRAND,
		PRODUCT_DIM.LAUNCH_DATE as LAUNCH_DATE,
		PRODUCT_DIM.DISCONTINUE_DATE as DISCONTINUE_DATE,
		STORE_DIM.STORE_KEY as store_dim.STORE_KEY,
		STORE_DIM.STORE_ID as STORE_ID,
		STORE_DIM.STORE_NAME as STORE_NAME,
		STORE_DIM.STORE_TYPE as STORE_TYPE,
		STORE_DIM.STORE_CITY as store_dim.CITY,
		STORE_DIM.STORE_STATE as store_dim.STATE,
		STORE_DIM.STORE_REGION as store_dim.REGION,
		STORE_DIM.DISTRICT as DISTRICT,
		STORE_DIM.OPEN_DATE as OPEN_DATE,
		STORE_DIM.CLOSE_DATE as CLOSE_DATE,
		STORE_DIM.MANAGER_NAME as MANAGER_NAME,
		STORE_DIM.STORE_PHONE as STORE_PHONE,
		DATE_DIM.DATE_KEY as date_dim.DATE_KEY,
		DATE_DIM.FULL_DATE as FULL_DATE,
		DATE_DIM.DAY_OF_WEEK as DAY_OF_WEEK,
		DATE_DIM.MONTH_NAME as MONTH_NAME,
		DATE_DIM.FISCAL_PERIOD as FISCAL_PERIOD,
		PROMO_DIM.PROMO_KEY as promo_dim.PROMO_KEY,
		PROMO_DIM.PROMO_ID as PROMO_ID,
		PROMO_DIM.PROMO_NAME as PROMO_NAME,
		PROMO_DIM.PROMO_TYPE as PROMO_TYPE,
		PROMO_DIM.CHANNEL as CHANNEL,
		PROMO_DIM.START_DATE as promo_dim.START_DATE,
		PROMO_DIM.END_DATE as promo_dim.END_DATE,
		PROMO_DIM.TARGET_SEGMENT as TARGET_SEGMENT
	)
	metrics (
		ORDER_FACT.TOTAL_GROSS_REVENUE as SUM(order_fact.gross_revenue),
		ORDER_FACT.TOTAL_NET_REVENUE as SUM(order_fact.net_revenue),
		ORDER_FACT.TOTAL_GROSS_PROFIT as SUM(order_fact.gross_profit),
		ORDER_FACT.TOTAL_NET_PROFIT as SUM(order_fact.net_profit),
		ORDER_FACT.TOTAL_DISCOUNT as SUM(order_fact.discount_amount),
		ORDER_FACT.TOTAL_SHIPPING as SUM(order_fact.shipping_amount),
		ORDER_FACT.TOTAL_TAX as SUM(order_fact.tax_amount),
		ORDER_FACT.TOTAL_QUANTITY_ORDERED as SUM(order_fact.quantity_ordered),
		ORDER_FACT.TOTAL_QUANTITY_RETURNED as SUM(order_fact.quantity_returned),
		ORDER_FACT.ORDER_LINE_COUNT as COUNT(*),
		ORDER_FACT.AVG_DAYS_TO_SHIP as AVG(order_fact.days_to_ship),
		ORDER_FACT.TOTAL_GROSS_REVENUE_BY_ORDER_STORE using (ORDER_TO_ORDER_STORE) as SUM(order_fact.gross_revenue),
		ORDER_FACT.TOTAL_GROSS_REVENUE_BY_SHIP_STORE using (ORDER_TO_SHIP_STORE) as SUM(order_fact.gross_revenue),
		ORDER_FACT.ORDER_LINE_COUNT_BY_ORDER_STORE using (ORDER_TO_ORDER_STORE) as COUNT(*),
		ORDER_FACT.ORDER_LINE_COUNT_BY_SHIP_STORE using (ORDER_TO_SHIP_STORE) as COUNT(*),
		ORDER_FACT.TOTAL_GROSS_REVENUE_BY_ORDER_DATE using (ORDER_TO_ORDER_DATE) as SUM(order_fact.gross_revenue),
		ORDER_FACT.TOTAL_GROSS_REVENUE_BY_SHIP_DATE using (ORDER_TO_SHIP_DATE) as SUM(order_fact.gross_revenue),
		ORDER_FACT.TOTAL_GROSS_REVENUE_BY_RETURN_DATE using (ORDER_TO_RETURN_DATE) as SUM(order_fact.gross_revenue),
		ORDER_FACT.ORDER_LINE_COUNT_BY_ORDER_DATE using (ORDER_TO_ORDER_DATE) as COUNT(*),
		ORDER_FACT.ORDER_LINE_COUNT_BY_SHIP_DATE using (ORDER_TO_SHIP_DATE) as COUNT(*),
		ORDER_FACT.ORDER_LINE_COUNT_BY_RETURN_DATE using (ORDER_TO_RETURN_DATE) as COUNT(*)
	)
	comment='Retail analytics semantic view with role-playing store and date dimensions';
